import React, { createContext, useContext, useState } from 'react';

const AppContext = createContext(null);

export function AppProvider({ children }) {
  const [user, setUser] = useState(null);

  const [preferences, setPreferences] = useState({
    dietType:    'Vegetarian',
    spiceLevel:  'Medium',
    cuisines:    ['indian'],
    healthGoals: ['healthy_eating'],
    allergies:   [],
    maxCalories: null,
    minProtein:  null,
    minGrade:    'c',
  });

  const [favorites, setFavorites]               = useState({ foods: [], restaurants: [] });
  const [savedFoodObjects, setSavedFoodObjects] = useState([]);
  const [darkMode, setDarkMode]                 = useState(true);
  const [cart, setCart]                         = useState([]);

  function toggleFavoriteFood(id) {
    setFavorites(prev => ({
      ...prev,
      foods: prev.foods.includes(id)
        ? prev.foods.filter(f => f !== id)
        : [...prev.foods, id],
    }));
  }

  function toggleFavoriteRestaurant(id) {
    setFavorites(prev => ({
      ...prev,
      restaurants: prev.restaurants.includes(id)
        ? prev.restaurants.filter(r => r !== id)
        : [...prev.restaurants, id],
    }));
  }

  function saveFoodObject(food) {
    setSavedFoodObjects(prev =>
      prev.find(f => f.id === food.id) ? prev : [...prev, food]
    );
  }

  function removeSavedFoodObject(id) {
    setSavedFoodObjects(prev => prev.filter(f => f.id !== id));
  }

  function addToCart(food) {
    setCart(prev => {
      const existing = prev.find(i => i.id === food.id);
      if (existing) return prev.map(i => i.id === food.id ? { ...i, qty: i.qty + 1 } : i);
      return [...prev, { ...food, qty: 1 }];
    });
  }

  function removeFromCart(id) {
    setCart(prev => prev.filter(i => i.id !== id));
  }

  return (
    <AppContext.Provider value={{
      user, setUser,
      preferences, setPreferences,
      favorites, toggleFavoriteFood, toggleFavoriteRestaurant,
      savedFoodObjects, saveFoodObject, removeSavedFoodObject,
      darkMode, setDarkMode,
      cart, addToCart, removeFromCart,
    }}>
      {children}
    </AppContext.Provider>
  );
}

export const useApp = () => useContext(AppContext);
